mapper.insert:
INSERT INTO document_upload_task (
    task_code, document_id, staging_path, target_path, status, execution_token, running_lease_until,
    retry_count, next_retry_at, failure_reason, created_at, updated_at
) VALUES (
    #{taskCode}, #{documentId}, #{stagingPath}, #{targetPath}, #{status}, #{executionToken}, #{runningLeaseUntil},
    #{retryCount}, #{nextRetryAt}, #{failureReason}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
FROM document_upload_task
WHERE status = 3
  AND next_retry_at <= #{now}
ORDER BY next_retry_at ASC
LIMIT #{limit}

mapper.update:
UPDATE document_upload_task
SET status = 0,
    next_retry_at = NULL,
    updated_at = #{now}
WHERE task_code = #{taskCode}
  AND status = 3
  AND next_retry_at <= #{now}

mapper.select:
SELECT 
FROM document_upload_task
WHERE status = 1
  AND running_lease_until <= #{now}
ORDER BY running_lease_until ASC
LIMIT #{limit}
